import { terminateConformanceRunner } from "./conformance-process.js";
import { spawn } from "node:child_process";
import { randomUUID } from "node:crypto";
import { existsSync } from "node:fs";
import {
  createServer,
  request as httpRequest,
  type IncomingHttpHeaders,
} from "node:http";
import { request as httpsRequest } from "node:https";
import type { Socket } from "node:net";
import path from "node:path";
import { redactOAuthValue } from "@superfunctions/oauth-core";

import {
  acquireRemoteCredential,
  redactRemoteCredential,
  validateRemoteCredentialHeaders,
  type McpFnRemoteCredential,
  type McpFnRemoteCredentialProvider,
} from "./remote-target.js";
import {
  normalizeMcpFnReportFailure,
  type McpFnReportFailure,
} from "./reports.js";

export const OFFICIAL_CONFORMANCE_VERSION = "0.1.16";

export interface OfficialConformanceOptions {
  url: string;
  suite?: "active" | "all" | "pending";
  scenario?: string;
  expectedFailures?: string;
  outputDir?: string;
  specVersion?: string;
  verbose?: boolean;
  cwd?: string;
  stdio?: "inherit" | "pipe";
  /** Environment names removed before spawning the upstream runner. */
  sensitiveEnvironmentVariables?: readonly string[];
}

export interface OfficialConformanceResult {
  formatVersion: 1;
  kind: "mcpfn.official-conformance-report";
  ok: boolean;
  suiteVersion: string;
  exitCode: number;
  stdout: string;
  stderr: string;
  failure?: McpFnReportFailure;
  /** Credential cleanup failure, separate from the upstream runner diagnosis. */
  cleanupFailure?: McpFnReportFailure;
}

export interface AuthenticatedConformanceProxy {
  /** Loopback URL to pass to the official conformance runner. */
  url: string;
  close(): Promise<void>;
}

export interface AuthenticatedConformanceProxyOptions {
  /** Fixed loopback MCP URL. Requests cannot select a different origin or path. */
  url: string;
  /** Headers injected into requests using the proxy's own authority. Values are never logged. */
  headers: HeadersInit;
}

export interface AuthenticatedOfficialConformanceOptions extends OfficialConformanceOptions {
  /** Preferred typed credential lifecycle. */
  credential?: McpFnRemoteCredential | McpFnRemoteCredentialProvider;
  /** Backward-compatible static header input. Prefer credential. */
  headers?: HeadersInit;
}

function validateAuthenticatedConformanceUrl(url: string): { upstream: URL; hostname: string } {
  const upstream = new URL(url);
  if (!["http:", "https:"].includes(upstream.protocol)) {
    throw new TypeError(
      "Authenticated conformance upstream must use HTTP or HTTPS",
    );
  }
  if (upstream.username || upstream.password || upstream.hash) {
    throw new TypeError(
      "Authenticated conformance upstream must not contain userinfo or a fragment",
    );
  }
  const hostname = normalizeLoopbackHostname(upstream.hostname);
  if (!hostname) {
    throw new TypeError(
      "Authenticated conformance upstream must use a literal loopback address",
    );
  }
  return { upstream, hostname };
}

/**
 * Start a loopback-only streaming proxy for runners that cannot send auth
 * headers. Authenticated requests use one fixed upstream authority and path.
 * Host-manipulation probes are forwarded without injected credentials.
 */
export async function createAuthenticatedConformanceProxy(
  options: AuthenticatedConformanceProxyOptions,
): Promise<AuthenticatedConformanceProxy> {
  const { upstream, hostname } = validateAuthenticatedConformanceUrl(options.url);
  const protocol = upstream.protocol === "https:" ? "https:" : "http:";
  const port = upstream.port === "" ? undefined : Number(upstream.port);
  const requestPath = `${upstream.pathname}${upstream.search}`;
  const injected = validateRemoteCredentialHeaders(options.headers);
  const activeRequests = new Set<ReturnType<typeof httpRequest>>();
  const activeSockets = new Set<Socket>();
  let proxyAuthority: string | undefined;
  const server = createServer((incoming, outgoing) => {
    if (!incoming.url?.startsWith("/")) {
      outgoing.writeHead(400).end();
      return;
    }
    const headers: IncomingHttpHeaders = { ...incoming.headers };
    delete headers.connection;
    const usesProxyAuthority = incoming.headers.host === proxyAuthority;
    injected.forEach((value, name) => {
      const normalizedName = name.toLowerCase();
      delete headers[normalizedName];
      if (usesProxyAuthority) headers[normalizedName] = value;
    });
    // Authenticated traffic is pinned to the upstream Host. Host-manipulation
    // probes retain their hostile value, but never receive injected credentials.
    if (usesProxyAuthority) headers.host = upstream.host;
    const transport = protocol === "https:" ? httpsRequest : httpRequest;
    const proxied = transport(
      {
        protocol,
        hostname,
        port,
        path: requestPath,
        method: incoming.method,
        headers,
      },
      (response) => {
        outgoing.writeHead(response.statusCode ?? 502, response.headers);
        response.pipe(outgoing);
      },
    );
    activeRequests.add(proxied);
    proxied.once("close", () => activeRequests.delete(proxied));
    proxied.once("error", () => {
      if (!outgoing.headersSent) outgoing.writeHead(502);
      outgoing.end();
    });
    incoming.once("aborted", () => proxied.destroy());
    incoming.pipe(proxied);
  });
  server.on("connection", (socket) => {
    activeSockets.add(socket);
    socket.once("close", () => activeSockets.delete(socket));
  });
  await new Promise<void>((resolve, reject) => {
    server.once("error", reject);
    server.listen(0, "127.0.0.1", () => {
      server.off("error", reject);
      resolve();
    });
  });
  const address = server.address();
  if (!address || typeof address === "string") {
    await new Promise<void>((resolve) => server.close(() => resolve()));
    throw new Error("Authenticated conformance proxy did not bind a TCP port");
  }
  const url = new URL(
    upstream.pathname + upstream.search,
    `http://127.0.0.1:${address.port}`,
  );
  proxyAuthority = url.host;
  let closePromise: Promise<void> | undefined;
  return {
    url: url.toString(),
    close: () => {
      closePromise ??= (async () => {
        for (const request of activeRequests) request.destroy();
        for (const socket of activeSockets) socket.destroy();
        if (!server.listening) return;
        await new Promise<void>((resolve, reject) => {
          server.close((error) => (error ? reject(error) : resolve()));
        });
      })();
      return closePromise;
    },
  };
}

function normalizeLoopbackHostname(
  hostname: string,
): string | undefined {
  const parts = hostname.split(".");
  if (parts.length === 4 && parts[0] === "127" && parts.every(part => /^\d{1,3}$/.test(part) && Number(part) <= 255)) return hostname;
  if (hostname === "[::1]") return "::1";
  return undefined;
}

function npxInvocation(args: string[]): { command: string; args: string[] } {
  if (process.platform !== "win32") return { command: "npx", args };
  const npmExecPath = process.env.npm_execpath;
  const candidates = [
    npmExecPath ? path.join(path.dirname(npmExecPath), "npx-cli.js") : undefined,
    path.resolve(path.dirname(process.execPath), "node_modules/npm/bin/npx-cli.js"),
    path.resolve(path.dirname(process.execPath), "../lib/node_modules/npm/bin/npx-cli.js"),
  ].filter((candidate): candidate is string => Boolean(candidate));
  const npxCli = candidates.find((candidate) => existsSync(candidate));
  if (!npxCli) {
    throw new Error("Unable to locate npm's npx-cli.js for the official MCP conformance runner");
  }
  return { command: process.execPath, args: [npxCli, ...args] };
}

export function buildOfficialConformanceArgs(
  options: OfficialConformanceOptions,
): string[] {
  const args = [
    "--yes",
    `@modelcontextprotocol/conformance@${OFFICIAL_CONFORMANCE_VERSION}`,
    `@modelcontextprotocol/conformance@${OFFICIAL_CONFORMANCE_VERSION}`,
    "server",
    "--url",
    options.url,
  ];
  if (options.suite) args.push("--suite", options.suite);
  if (options.scenario) args.push("--scenario", options.scenario);
  if (options.expectedFailures) {
    args.push("--expected-failures", options.expectedFailures);
  }
  if (options.outputDir) args.push("--output-dir", options.outputDir);
  if (options.specVersion) args.push("--spec-version", options.specVersion);
  if (options.verbose) args.push("--verbose");
  return args;
}

export function buildOfficialConformanceEnvironment(
  sensitiveNames: readonly string[] = [],
  source: NodeJS.ProcessEnv = process.env,
): NodeJS.ProcessEnv {
  const environment = { ...source };
  const sensitive = new Set(sensitiveNames.map((name) => name.toLowerCase()));
  for (const name of Object.keys(environment)) {
    if (sensitive.has(name.toLowerCase())) delete environment[name];
  }
  environment.PATH = [path.dirname(process.execPath), environment.PATH]
    .filter(Boolean)
    .join(path.delimiter);
  return environment;
}

export async function runOfficialConformance(options: OfficialConformanceOptions): Promise<OfficialConformanceResult> {
  return runConformance(options, value => String(redactOAuthValue(value, { maxStringLength: 262_144 })));
}

async function runConformance(
  options: OfficialConformanceOptions,
  redactOutput: (value: string) => string,
): Promise<OfficialConformanceResult> {
  const nodeMajor = Number.parseInt(process.versions.node.split(".")[0] ?? "0", 10);
  if (nodeMajor < 22) {
    throw new Error(
      `Official MCP conformance ${OFFICIAL_CONFORMANCE_VERSION} requires Node.js 22 or newer; current runtime is ${process.versions.node}`,
    );
  }
  const args = buildOfficialConformanceArgs(options);
  const invocation = npxInvocation(args);
  const childEnvironment = buildOfficialConformanceEnvironment(
    options.sensitiveEnvironmentVariables,
  );

  return await new Promise<OfficialConformanceResult>((resolve) => {
    const child = spawn(invocation.command, invocation.args, {
      detached: process.platform !== "win32",
      cwd: options.cwd,
      env: childEnvironment,
      stdio: options.stdio === "inherit" ? "inherit" : "pipe",
    });
    let stdout = "";
    let stderr = "";
    let capturedBytes = 0;
    let outputExceeded = false;
    const capture = (chunk: string, stream: "stdout" | "stderr") => {
      if (outputExceeded) return;
      capturedBytes += Buffer.byteLength(chunk, "utf8");
      if (capturedBytes > 262_144) {
        outputExceeded = true;
        stdout = ""; stderr = "";
        // Always settle the failed report after the bounded termination attempt,
        // even if the wrapper never emits close (for example, a failed taskkill).
        void terminateConformanceRunner(child).finally(() => finish(1));
        return;
      }
      if (stream === "stdout") stdout += chunk.toString();
      else stderr += chunk.toString();
    };
    child.stdout?.setEncoding("utf8");
    child.stderr?.setEncoding("utf8");
    child.stdout?.on("data", chunk => capture(chunk, "stdout"));
    child.stderr?.on("data", chunk => capture(chunk, "stderr"));
    let settled = false;
    child.once("error", (error) => {
      if (settled) return;
      settled = true;
      const failure = normalizeMcpFnReportFailure(error, "upstream-conformance");
      resolve({
        formatVersion: 1,
        kind: "mcpfn.official-conformance-report",
        ok: false,
        suiteVersion: OFFICIAL_CONFORMANCE_VERSION,
        exitCode: 1,
        stdout: "",
        stderr: failure.message,
        failure,
      });
    });
    const finish = (code: number | null) => {
      if (settled) return;
      settled = true;
      let exitCode = code ?? 1;
      let safeStdout = "";
      let safeStderr = "";
      try {
        if (outputExceeded) throw new Error("capture limit");
        safeStdout = redactOutput(stdout);
        safeStderr = redactOutput(stderr);
      } catch {
        exitCode = 1;
        safeStdout = "";
        safeStderr = outputExceeded ? "Conformance output exceeded its capture limit" : "Conformance output omitted because credential redaction exceeded its bounds";
      }
      const failure = exitCode === 0
        ? undefined
        : normalizeMcpFnReportFailure(
          new Error(safeStderr || safeStdout || `Official conformance exited ${exitCode}`),
          "upstream-conformance",
        );
      resolve({
        formatVersion: 1,
        kind: "mcpfn.official-conformance-report",
        ok: exitCode === 0,
        suiteVersion: OFFICIAL_CONFORMANCE_VERSION,
        exitCode,
        stdout: safeStdout,
        stderr: safeStderr,
        ...(failure ? { failure } : {}),
      });
    };
    child.once("close", finish);
  });
}

const retainedConformanceCleanup = new WeakMap<Error, () => Promise<void>>();

/** Cleanup failed after retries. Retain this error and call retryCleanup(). */
export class McpFnConformanceCleanupError extends Error {
  constructor(release: () => Promise<void>, readonly result?: OfficialConformanceResult) {
    super("Authenticated conformance credential cleanup failed; retry cleanup");
    this.name = "McpFnConformanceCleanupError";
    retainedConformanceCleanup.set(this, release);
  }
  async retryCleanup(): Promise<void> {
    const release = retainedConformanceCleanup.get(this);
    if (!release) return;
    try { await release(); }
    catch { throw this; }
    retainedConformanceCleanup.delete(this);
  }
}

/**
 * Run the pinned official suite against an authenticated MCP endpoint.
 * Always captures stdio (even when inherit is requested) to redact credentials.
 * outputDir is rejected before acquisition; only the returned redacted result is safe to persist.
 */
export async function runAuthenticatedOfficialConformance(
  options: AuthenticatedOfficialConformanceOptions,
): Promise<OfficialConformanceResult> {
  if (options.outputDir !== undefined) throw new TypeError("Authenticated conformance does not support outputDir; serialize the redacted result instead");
  const { headers, credential, ...conformance } = options;
  if ((headers === undefined) === (credential === undefined)) {
    throw new TypeError("Provide exactly one of credential or headers for authenticated conformance");
  }
  validateAuthenticatedConformanceUrl(conformance.url);
  const lease = await acquireRemoteCredential(
    credential ?? { headers: headers! },
    {
      url: conformance.url,
      requestId: randomUUID(),
    },
  );
  let proxy: AuthenticatedConformanceProxy | undefined;
  let result: OfficialConformanceResult | undefined;
  let operationFailure: { error: Error } | undefined;
  const safeFailure = (error: unknown): { error: Error } => {
    let message = "Authenticated conformance operation failed";
    try { message = redactRemoteCredential(lease.credential, error instanceof Error ? error.message : String(error)); }
    catch { /* Keep a safe fallback if redaction exceeds its budget. */ }
    return { error: new Error(message) };
  };
  try {
    proxy = await createAuthenticatedConformanceProxy({
      url: conformance.url,
      headers: lease.credential.headers,
    });
    result = redactRemoteCredential(lease.credential, await runConformance({ ...conformance, stdio: "pipe", url: proxy.url }, value => String(redactRemoteCredential(lease.credential, value))), { preserveKeys: true });
  } catch (error) {
    operationFailure = safeFailure(error);
  }
  try { await proxy?.close(); }
  catch (error) { operationFailure ??= safeFailure(error); }
  let released = false;
  for (let attempt = 0; attempt < 3; attempt++) {
    try { await lease.release(); released = true; break; } catch { /* Retry transient revocation failure. */ }
  }
  if (!released) {
    const message = "Authenticated conformance credential cleanup failed; retry cleanup";
    const cleanupFailure = normalizeMcpFnReportFailure(new Error(message), lease.cleanupPhase());
    const failedResult = result ? { ...result, ok: false, exitCode: result.exitCode || 1,
      cleanupFailure,
      ...(result.failure ? {} : { failure: cleanupFailure }),
    } : undefined;
    throw new McpFnConformanceCleanupError(() => lease.release(), failedResult);
  }
  if (operationFailure) throw operationFailure.error;
  if (!result) throw new Error("Conformance produced no result");
  return result;
}
import { McpFnRedactionLimitError, beginTargetCredentialRedaction, redactTargetCredentials } from "./remote-target.js";
import type { Implementation, ServerCapabilities } from "@modelcontextprotocol/sdk/types.js";
import type {
  McpFnDiagnosticEvent,
  McpFnTarget,
  McpFnTargetDescriptor,
} from "@mcpfn/client";
import type { McpFnManifest } from "@mcpfn/core";

import { assertManifestContract, McpFnAssertionError, stableJson } from "./assertions.js";
import { McpFnTestClient, type McpFnTestClientOptions } from "./client.js";
import {
  MCPFN_REPORT_SCHEMA_VERSION,
  MCPFN_TESTING_VERSION,
  normalizeMcpFnReportFailure,
  type McpFnReportFailure,
} from "./reports.js";
import {
  runScenarios,
  type McpFnScenario,
  type McpFnScenarioResult,
} from "./scenarios.js";

export interface RunMcpFnTargetSuiteOptions {
  target: McpFnTarget;
  scenarios?: McpFnScenario[];
  manifest?: McpFnManifest;
  expectedToolNames?: readonly string[];
  clientInfo?: Implementation;
  client?: McpFnTestClientOptions;
  scenarioRun?: NonNullable<Parameters<typeof runScenarios>[2]>;
  /** Aggregate JSON size cap. Defaults to 1 MiB. */
  maxReportBytes?: number;
  /** Diagnostic timeline count cap. Defaults to 500. */
  maxTimelineEvents?: number;
}

export interface McpFnTargetSuiteReport {
  formatVersion: 1;
  kind: "mcpfn.target-suite-report";
  status: "complete" | "incomplete";
  runtime: {
    node: string;
    scenarioFormatVersion: 1;
    reportSchemaVersion: string;
    packages: { testing: string };
  };
  ok: boolean;
  target: McpFnTargetDescriptor;
  server?: Implementation;
  capabilities?: ServerCapabilities;
  manifestChecked: boolean;
  manifestHash?: string;
  total: number;
  passed: number;
  failed: number;
  incomplete: number;
  droppedResults: number;
  droppedObservedEvents: number;
  redactionOmittedObservedEvents?: number;
  incompleteReason?: string;
  failure?: McpFnReportFailure;
  timeline: McpFnDiagnosticEvent[];
  droppedTimelineEvents: number;
  results: McpFnScenarioResult[];
}

const suiteCleanupOwners = new WeakMap<McpFnTargetSuiteCleanupError, { close: () => Promise<void>; pending?: Promise<void> }>();

/** Final cleanup failed. The bounded report is a snapshot; retain this error to retry. */
export class McpFnTargetSuiteCleanupError extends Error {
  constructor(readonly report: McpFnTargetSuiteReport, close: () => Promise<void>) {
    super("Target suite cleanup failed; retain this error and retryCleanup()");
    this.name = "McpFnTargetSuiteCleanupError";
    suiteCleanupOwners.set(this, { close });
  }

  retryCleanup(): Promise<void> {
    const owner = suiteCleanupOwners.get(this);
    if (!owner) return Promise.resolve();
    if (owner.pending) return owner.pending;
    const pending = Promise.resolve().then(owner.close).then(
      () => { suiteCleanupOwners.delete(this); },
      () => { throw this; },
    ).finally(() => { owner.pending = undefined; });
    owner.pending = pending;
    return pending;
  }
}

/** Runs local, stdio, HTTP, or custom targets through the production session engine. */
export async function runMcpFnTargetSuite(
  options: RunMcpFnTargetSuiteOptions,
): Promise<McpFnTargetSuiteReport> {
  const finishRedaction = beginTargetCredentialRedaction(options.target);
  try { return await runTargetSuite(options); }
  finally { finishRedaction(); }
}

/** Apply the target-owned scrubber before the bounded generic artifact pass. */
function redactSuiteArtifact<T>(target: McpFnTarget, value: T, options: { preserveKeys?: boolean } = {}): T {
  const scrubbed = target.redact ? target.redact(value, options) : value;
  return redactTargetCredentials(target, scrubbed, options);
}

async function runTargetSuite(options: RunMcpFnTargetSuiteOptions): Promise<McpFnTargetSuiteReport> {
  const timeline: McpFnDiagnosticEvent[] = [];
  let droppedTimelineEvents = 0;
  let timelineBytes = 0;
  let timelineCountExceeded = false;
  let timelineBytesExceeded = false;
  let timelineSerializationFailed = false;
  let timelineRedactionFailed = false;
  const timelineSizes: number[] = [];
  const maxTimelineEvents = options.maxTimelineEvents ?? 500;
  if (!Number.isInteger(maxTimelineEvents) || maxTimelineEvents < 1) {
    throw new Error("maxTimelineEvents must be a positive integer");
  }
  const maxReportBytes = options.maxReportBytes ?? 1_048_576;
  validateReportCap(maxReportBytes);
  const consumerDiagnostic = options.client?.diagnostics;
  let client: McpFnTestClient | undefined;
  let manifestChecked = false;
  let failure: McpFnReportFailure | undefined;
  let cleanupFailure: McpFnReportFailure | undefined;
  let retainedCleanup: (() => Promise<void>) | undefined;
  let capturedTarget: McpFnTargetDescriptor = { kind: "custom" };
  let capturedManifestHash: string | undefined;
  let projectionFailed = false;
  let execution: {
    results: McpFnScenarioResult[];
    server?: Implementation;
    capabilities?: ServerCapabilities;
  } = { results: [] };
  try {
    // Known transport kinds are structural and safe even if acquisition fails.
    // Defer arbitrary descriptor values until credentials are available to redact.
    const kind = options.target.kind;
    if (["stdio", "streamable-http", "authenticated-streamable-http", "in-memory", "custom"].includes(kind)) {
      capturedTarget = { kind };
    }
    client = McpFnTestClient.createTarget(
      options.target,
      options.clientInfo ?? { name: "mcpfn-suite", version: "0.0.1" },
      {
        ...options.client,
        diagnostics: async (event) => {
          if (client?.session.isRedactionOmission(event)) {
            // Retain the safe fallback as evidence, but count the original omission.
            timelineRedactionFailed = true;
            droppedTimelineEvents += 1;
          }
          if (event.phase === "transport-close" && event.outcome === "failed") {
            cleanupFailure = normalizeMcpFnReportFailure({
              name: "CleanupError", message: "Target cleanup failed",
              code: event.code, phase: event.phase,
            });
          }
          // Production-client dispatch already applied the custom target hook.
          const safeEvent = redactTargetCredentials(options.target, event, { preserveKeys: true });
          let bytes: number;
          try {
            const json = JSON.stringify(safeEvent, (_key, value: unknown) => {
              if (value === undefined || (typeof value === "number" && !Number.isFinite(value))) {
                throw new Error("Diagnostic contains a non-JSON value");
              }
              return value;
            });
            bytes = Buffer.byteLength(json);
            structuredClone(safeEvent);
          }
          catch {
            timelineSerializationFailed = true;
            droppedTimelineEvents += 1;
            await consumerDiagnostic?.(safeEvent);
            return;
          }
          if (bytes > maxReportBytes) {
            timelineBytesExceeded = true;
            droppedTimelineEvents += 1;
          } else {
            timeline.push(safeEvent);
            timelineSizes.push(bytes);
            timelineBytes += bytes;
            while (timeline.length > maxTimelineEvents || timelineBytes > maxReportBytes) {
              timelineCountExceeded ||= timeline.length > maxTimelineEvents;
              timelineBytesExceeded ||= timelineBytes > maxReportBytes;
              timeline.shift();
              timelineBytes -= timelineSizes.shift()!;
              droppedTimelineEvents += 1;
            }
          }
          await consumerDiagnostic?.(safeEvent);
        },
      },
    );
    await client.session.connect();
    if (options.manifest) {
      manifestChecked = true;
      await assertManifestContract(client, options.manifest, {
        expectedToolNames: options.expectedToolNames,
      });
    }
    if (!options.manifest && options.expectedToolNames) {
      const actual = (await client.listTools()).map((tool) => tool.name).sort((left, right) => left < right ? -1 : left > right ? 1 : 0);
      const expected = [...options.expectedToolNames].sort((left, right) => left < right ? -1 : left > right ? 1 : 0);
      if (stableJson(actual) !== stableJson(expected)) {
        throw new McpFnAssertionError(`Tool inventory mismatch: expected ${stableJson(expected)}, actual ${stableJson(actual)}`);
      }
    }
    execution = {
      results: await runScenarios(
        client,
        options.scenarios ?? [],
        options.scenarioRun,
      ),
      server: client.session.getServerVersion(),
      capabilities: client.session.getServerCapabilities(),
    };
  } catch (error) {
    try {
      failure = normalizeMcpFnReportFailure(redactSuiteArtifact(options.target, error, { preserveKeys: true }));
    } catch {
      // Arbitrary error properties/proxies can throw, including secret-bearing errors.
      failure = normalizeMcpFnReportFailure({ name: "RedactionError", code: "MCPFN_REDACTION_FAILED", message: "Target failure omitted because credential redaction failed" });
    }
  } finally {
    try {
      // Custom hooks may depend on credentials cleared by close. Capture every
      // target-controlled report value while the session still owns that state.
      if (client?.session.state === "connected") {
        const { kind, ...descriptor } = options.target.describe();
        capturedTarget = { ...redactSuiteArtifact(options.target, descriptor, { preserveKeys: false }), kind };
        capturedManifestHash = options.manifest
          ? redactSuiteArtifact(options.target, options.manifest.hash, { preserveKeys: false })
          : undefined;
        execution = {
          server: execution.server === undefined
            ? undefined
            : redactSuiteArtifact(options.target, execution.server, { preserveKeys: false }),
          capabilities: execution.capabilities === undefined
            ? undefined
            : redactSuiteArtifact(options.target, execution.capabilities, { preserveKeys: false }),
          results: execution.results.map(result => ({
            ...result,
            name: redactSuiteArtifact(options.target, result.name, { preserveKeys: false }),
            operation: redactSuiteArtifact(options.target, result.operation, { preserveKeys: false }),
            ...(result.tool === undefined ? {} : {
              tool: redactSuiteArtifact(options.target, result.tool, { preserveKeys: false }),
            }),
          })),
        };
      } else if (execution.results.length || execution.server || execution.capabilities) {
        projectionFailed = true;
      }
    } catch { projectionFailed = true; }
    try {
      await client?.close();
    } catch (error) {
      const owner = client;
      if (owner) retainedCleanup = () => owner.close();
      cleanupFailure = normalizeMcpFnReportFailure({ name: "CleanupError", message: "Target cleanup failed", code: "MCPFN_TARGET_CLEANUP_FAILED", phase: "transport-close" });
      if (!failure) failure = cleanupFailure;
    }
  }
  failure ??= cleanupFailure;
  const results = execution.results;
  const failed = results.filter((result) => result.status === "failed").length;
  const incomplete = results.filter((result) => result.status === "incomplete").length;
  const droppedObservedEvents = results.reduce(
    (total, result) => total + (result.droppedObservedEvents ?? 0),
    0,
  );
  const redactionOmittedObservedEvents = results.reduce(
    (total, result) => total + (result.redactionOmittedObservedEvents ?? 0),
    0,
  );
  const overflowedObservedEvents = droppedObservedEvents - redactionOmittedObservedEvents;
  const artifactIncomplete = Boolean(failure) || incomplete > 0 ||
    droppedTimelineEvents > 0 ||
    droppedObservedEvents > 0;
  const report: McpFnTargetSuiteReport = {
    formatVersion: 1,
    kind: "mcpfn.target-suite-report",
    status: artifactIncomplete ? "incomplete" : "complete",
    runtime: {
      node: process.version,
      scenarioFormatVersion: 1,
      reportSchemaVersion: MCPFN_REPORT_SCHEMA_VERSION,
      packages: { testing: MCPFN_TESTING_VERSION },
    },
    ok: failed === 0 && !artifactIncomplete,
    target: capturedTarget,
    server: execution.server,
    capabilities: execution.capabilities,
    manifestChecked,
    ...(capturedManifestHash === undefined ? {} : { manifestHash: capturedManifestHash }),
    total: results.length,
    passed: results.length - failed - incomplete,
    failed,
    incomplete,
    droppedResults: 0,
    droppedObservedEvents,
    ...(redactionOmittedObservedEvents > 0 ? { redactionOmittedObservedEvents } : {}),
    ...(failure || droppedTimelineEvents > 0 || droppedObservedEvents > 0
      ? {
        incompleteReason: [
          ...(failure ? [`${failure.layer}: ${failure.message}`] : []),
          ...(cleanupFailure ? [`Cleanup: ${cleanupFailure.message}`] : []),
          ...(timelineSerializationFailed ? ["Diagnostic timeline contained non-JSON data"] : []),
          ...(timelineRedactionFailed ? ["Diagnostic timeline redaction failed; original events omitted"] : []),
          ...(timelineCountExceeded ? ["Diagnostic timeline exceeded maxTimelineEvents"] : []),
          ...(timelineBytesExceeded ? ["Diagnostic timeline exceeded maxReportBytes"] : []),
          ...(redactionOmittedObservedEvents > 0
            ? ["Observed client events were omitted because credential redaction failed"]
            : []),
          ...(overflowedObservedEvents > 0
            ? ["Observed client events exceeded maxObservedEvents"]
            : []),
        ].join("; "),
      }
      : {}),
    ...(failure ? { failure } : {}),
    timeline,
    droppedTimelineEvents,
    results,
  };
  let finalized: McpFnTargetSuiteReport;
  try {
    if (projectionFailed) throw new Error("Report payload redaction failed");
    // Custom redaction already completed before cleanup. Built-in report scopes
    // remain active here for bounded final serialization.
    finalized = enforceReportCap(redactTargetCredentials(options.target, report, { preserveKeys: true }), maxReportBytes);
  } catch (error) {
    finalized = enforceReportCap({ ...report, ok: false, status: "incomplete",
      incompleteReason: error instanceof McpFnRedactionLimitError
        ? "Credential redaction exceeded its traversal budget"
        : "Report content omitted because safe serialization failed",
      target: { kind: "custom" }, server: undefined, capabilities: undefined, manifestHash: undefined,
      failure: undefined, results: [], timeline: [],
      droppedResults: report.results.length, droppedTimelineEvents: report.droppedTimelineEvents + report.timeline.length,
    }, maxReportBytes);
  }
  if (retainedCleanup) throw new McpFnTargetSuiteCleanupError(finalized, retainedCleanup);
  return finalized;
}

function enforceReportCap(
  report: McpFnTargetSuiteReport,
  maxBytes: number,
): McpFnTargetSuiteReport {
  validateReportCap(maxBytes);
  const bounded = structuredClone(report);
  if (jsonBytes(bounded) > maxBytes) {
    bounded.ok = false;
    bounded.status = "incomplete";
    bounded.incompleteReason = "Report content exceeded maxReportBytes and was truncated";
  }
  while (jsonBytes(bounded) > maxBytes && bounded.results.length > 0) {
    bounded.results.pop();
    bounded.droppedResults += 1;
  }
  if (jsonBytes(bounded) > maxBytes) {
    bounded.target = { kind: report.target.kind };
    bounded.server = undefined;
    bounded.capabilities = undefined;
    bounded.timeline = [];
    bounded.droppedTimelineEvents += report.timeline.length;
    if (bounded.failure) {
      bounded.failure.details = undefined;
      bounded.failure.message = "Target operation failed; details omitted to fit report budget";
    }
  }
  if (bounded.droppedResults > 0 || jsonBytes(bounded) > maxBytes) {
    bounded.ok = false;
    bounded.status = "incomplete";
    bounded.incompleteReason = "Report content exceeded maxReportBytes and was truncated";
  }
  if (jsonBytes(bounded) > maxBytes) {
    throw new Error("The minimum target suite report exceeds maxReportBytes");
  }
  return bounded;
}

function validateReportCap(maxBytes: number): void {
  if (!Number.isInteger(maxBytes) || maxBytes < 1_024) {
    throw new Error("maxReportBytes must be an integer of at least 1024");
  }
}

function jsonBytes(value: unknown): number {
  return new TextEncoder().encode(JSON.stringify(value)).byteLength;
}
function executeEventScenario(
  scenario: McpFnEventScenario,
  observedEvents: McpFnClientEvent[],
): void {
  const matching = observedEvents.filter((event) => event.kind === scenario.event);
  if (matching.length < (scenario.minimum ?? 1)) {
    throw new McpFnAssertionError(
      `Expected at least ${scenario.minimum ?? 1} ${scenario.event} event(s), received ${matching.length}`,
    );
  }
  if (scenario.expectPayload !== undefined) {
    assertExpected(matching.at(-1)?.payload, scenario.expectPayload);
  }
}

async function executeAuthScenario(
  scenario: McpFnAuthScenario,
  signal: AbortSignal,
  runOptions: McpFnScenarioRunOptions,
): Promise<void> {
  if (!runOptions.auth) {
    throw new McpFnAssertionError("auth.assert requires a scenario auth adapter");
  }
  assertExpected(await runOptions.auth(scenario, signal), scenario.expect);
}

function truncateError(value: string, options: McpFnScenarioRunOptions, client: McpFnTestClient): string {
  let redacted = "Scenario error omitted because credential redaction failed";
  try { redacted = String(client.session.redact(value)); }
  catch { /* Report safely even when a diagnostic exceeds the redaction budget. */ }
  const maxBytes = options.maxErrorBytes ?? 4_096;
  const bytes = new TextEncoder().encode(redacted);
  if (bytes.byteLength <= maxBytes) return redacted;
  return `${new TextDecoder().decode(bytes.slice(0, Math.max(0, maxBytes - 16)))}...[TRUNCATED]`;
}

function defaultSideEffect(operation: string): McpFnScenarioSideEffect {
  if (operation === "tools.call" || operation === "tools.call:task") {
    return "non-idempotent";
  }
  if (operation === "tasks.cancel") return "idempotent";
  return "none";
}

function compareCodeUnits(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

function assertExpected(actual: unknown, expected: unknown): void {
  if (expected !== undefined && stableJson(actual) !== stableJson(expected)) {
    throw new McpFnAssertionError(
      `Scenario result mismatch\nexpected: ${stableJson(expected)}\nactual:   ${stableJson(actual)}`,
    );
  }
}

function isToolScenario(scenario: McpFnScenario): scenario is McpFnToolScenario {
  return "tool" in scenario;
}
  const omitted = report.results.length - results.length;
  const cases = results.map((result) => {
    const duration = Math.max(0, result.durationMs ?? 0) / 1_000;
    const failure = result.status === "passed"
      ? ""
      : junitFailure(
        result.error ?? `Scenario ${result.status}`,
        result.status === "failed" ? "scenario" : "incomplete",
      );
    return `    <testcase name="${xml(result.name)}" classname="mcpfn.scenario" time="${duration.toFixed(3)}">${failure}</testcase>`;
  });
  if (safe.failure) {
    cases.unshift(
      `    <testcase name="${xml(safe.failure.phase ?? "target")}" classname="mcpfn.${xml(safe.failure.layer)}" time="0.000">${junitFailure(safe.failure.message, safe.failure.code ?? safe.failure.layer)}</testcase>`,
    );
  }
  if (safe.status === "incomplete" || omitted > 0 || (!safe.ok && !safe.failure && results.every((result) => result.status === "passed"))) {
    cases.push(`    <testcase name="suite-incomplete" classname="mcpfn.report" time="0.000">${junitFailure(safe.incompleteReason ?? "Suite evidence is incomplete or omitted", "incomplete")}</testcase>`);
  }
  if (cases.length === 0) {
    cases.push(
      '    <testcase name="target-suite" classname="mcpfn.target" time="0.000"></testcase>',
    );
  }
  const failures = cases.filter((entry) => entry.includes("<failure ")).length;
  let serialized = junitDocument(safe, cases, failures);
  if (bytes(serialized) <= maxBytes) return serialized;

  const boundedCases = [
    `    <testcase name="artifact-cap" classname="mcpfn.report" time="0.000">${junitFailure("JUnit content exceeded maxBytes and was truncated", "incomplete")}</testcase>`,
  ];
  serialized = junitDocument(safe, boundedCases, 1, true);
  if (bytes(serialized) > maxBytes) {
    throw new Error("The minimum McpFn JUnit report exceeds maxBytes");
  }
  return serialized;
}

function junitDocument(
  report: McpFnTargetSuiteReport,
  cases: string[],
  failures: number,
  truncated = false,
): string {
  const suiteName = String(redactOAuthValue(`mcpfn:${report.target.kind}`));
  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    `<testsuite name="${xml(suiteName)}" tests="${cases.length}" failures="${failures}" errors="0" skipped="0">`,
    "  <properties>",
    `    <property name="mcpfn.report.schema" value="${xml(MCPFN_REPORT_SCHEMA_VERSION)}"/>`,
    `    <property name="mcpfn.testing.version" value="${xml(MCPFN_TESTING_VERSION)}"/>`,
    `    <property name="node.version" value="${xml(report.runtime.node)}"/>`,
    `    <property name="artifact.truncated" value="${truncated}"/>`,
    "  </properties>",
    ...cases,
    "</testsuite>",
    "",
  ].join("\n");
}

function junitFailure(message: string, type: string): string {
  const safe = String(redactOAuthValue(message, { maxStringLength: 4_096 }));
  return `<failure type="${xml(type)}" message="${xml(safe)}">${xml(safe)}</failure>`;
}

function failureLayer(phase: string | undefined): McpFnFailureLayer {
  if (phase === "resource-discovery" || phase === "transport-connect") {
    return "resource-server";
  }
  if (
    phase === "authorization-server-discovery" ||
    phase === "client-registration" ||
    phase === "authorization-request" ||
    phase === "authorization-callback" ||
    phase === "token-exchange" ||
    phase === "token-refresh" ||
      "code_challenge",
      derivePkceS256Challenge(fixture.authorization.codeVerifier),
    );
    authorization.searchParams.set("code_challenge_method", "S256");
    authorization.searchParams.set("state", fixture.authorization.state);
    authorization.searchParams.set("resource", fixture.authorization.resource);
    authorization.searchParams.set("scope", fixture.authorization.scopes.join(" "));
    responseStatus = undefined;
    const authorizationResponse = await target.request(new Request(authorization, {
      redirect: "manual",
    }));
    responseStatus = authorizationResponse.status;
    const authorizationError = await oauthError(authorizationResponse);
    if (authorizationError) {
      await validateOAuthRejection(authorizationResponse, fixture, target.issuer, true);
      return assessHostedCase(fixture, phase, authorizationResponse.status, authorizationError);
    }
    if (!isRedirect(authorizationResponse.status)) {
      throw new Error(`Authorization request did not redirect (HTTP ${authorizationResponse.status})`);
    }
    const code = validatedRedirectCode(authorizationResponse, fixture, target.issuer);
    if (fixture.token) {
      phase = fixture.token.grantType === "refresh_token"
        ? "token-refresh"
        : "token-exchange";
      const tokenBody = new URLSearchParams({
        grant_type: fixture.token.grantType,
        client_id: fixture.authorization.clientId,
      });
      if (fixture.token.grantType === "authorization_code") {
        tokenBody.set("code", fixture.token.code ?? code);
        tokenBody.set("redirect_uri", fixture.authorization.redirectUri);
        tokenBody.set("code_verifier", fixture.authorization.codeVerifier);
        tokenBody.set("resource", fixture.authorization.resource);
      } else if (fixture.token.refreshToken) {
        tokenBody.set("refresh_token", fixture.token.refreshToken);
        tokenBody.set("resource", fixture.authorization.resource);
      }
      responseStatus = undefined;
      const tokenResponse = await target.request(new Request(
        new URL("token", ensureTrailingSlash(target.issuer)),
        {
          method: "POST",
          redirect: "manual",
          headers: { "content-type": "application/x-www-form-urlencoded" },
          body: tokenBody,
        },
      ));
      responseStatus = tokenResponse.status;
      const tokenError = await oauthError(tokenResponse);
      if (tokenError) {
        await validateOAuthRejection(tokenResponse, fixture, target.issuer);
        return assessHostedCase(fixture, phase, tokenResponse.status, tokenError);
      }
      if (!tokenResponse.ok) throw new Error(`Token request returned HTTP ${tokenResponse.status}`);
      const tokenSet = await validatedTokenSet(tokenResponse);
      responseStatus = tokenResponse.status;
      if (fixture.token.refreshAfterExchange) {
        if (typeof tokenSet.refresh_token !== "string" || !tokenSet.refresh_token) {
          throw new Error("Authorization-code response did not include a refresh token");
        }
        phase = "token-refresh";
        responseStatus = undefined;
        const refreshResponse = await target.request(new Request(
          new URL("token", ensureTrailingSlash(target.issuer)),
          {
            method: "POST",
            redirect: "manual",
            headers: { "content-type": "application/x-www-form-urlencoded" },
            body: new URLSearchParams({
              grant_type: "refresh_token",
              client_id: fixture.authorization.clientId,
              refresh_token: tokenSet.refresh_token,
              resource: fixture.authorization.resource,
            }),
          },
        ));
        responseStatus = refreshResponse.status;
        const refreshError = await oauthError(refreshResponse);
        if (refreshError) {
          await validateOAuthRejection(refreshResponse, fixture, target.issuer);
          return assessHostedCase(fixture, phase, refreshResponse.status, refreshError);
        }
        if (!refreshResponse.ok) {
          throw new Error(`Refresh request returned HTTP ${refreshResponse.status}`);
        }
        await validatedTokenSet(refreshResponse);
        responseStatus = refreshResponse.status;
      }
    }
    return assessHostedCase(fixture, phase, responseStatus);
  } catch (error) {
    const redacted = redactOAuthValue(error);
    const safe = redacted && typeof redacted === "object" ? redacted as Record<string, unknown> : {};
    const code = typeof safe.code === "string" ? safe.code : undefined;
    const message = typeof safe.message === "string" ? safe.message : String(redacted);
    return assessHostedCase(fixture, phase, responseStatus, code, message || "Hosted adapter failed");
  }
}

function assessHostedCase(
  fixture: McpFnHostedAuthorizationCase,
  phase: McpFnHostedAuthorizationCaseResult["phase"],
  responseStatus?: number,
  errorCode?: string,
  error?: string,
): McpFnHostedAuthorizationCaseResult {
  const observedOutcome = errorCode || error ? "rejected" : "allowed";
  const expected = fixture.expected;
  const passed = !error && observedOutcome === expected.outcome &&
    (expected.errorCode === undefined || expected.errorCode === errorCode) &&
    (expected.phase === undefined || expected.phase === phase);
  return {
    formatVersion: 1,
    id: fixture.id,
    host: fixture.host,
    status: passed ? "passed" : "failed",
    phase,
    layer: phase === "client-registration" ? "mcpfn-preflight" : "authorization-server",
    ...(responseStatus === undefined ? {} : { responseStatus }),
    ...(errorCode ? { errorCode } : {}),
    ...(!passed || error ? {
      error: error ??
        `Expected ${expected.outcome}${expected.errorCode ? `:${expected.errorCode}` : ""}, received ${observedOutcome}${errorCode ? `:${errorCode}` : ""}`,
    } : {}),
  };
}

function isJsonResponse(response: Response): boolean {
  const mediaType = (response.headers.get("content-type") ?? "").split(";", 1)[0].trim().toLowerCase();
  return mediaType === "application/json" || /^application\/[a-z0-9!#$&^_.+-]+\+json$/.test(mediaType);
}

async function oauthError(response: Response): Promise<string | undefined> {
  const location = response.headers.get("location");
  if (location) {
    const code = new URL(location).searchParams.get("error");
    if (code) return code;
  }
  if (!isJsonResponse(response)) return undefined;
  const body = await response.clone().json().catch(() => undefined) as
    | { error?: unknown }
    | undefined;
  return typeof body?.error === "string" ? body.error : undefined;
}

async function validateOAuthRejection(
  response: Response,
  fixture: McpFnHostedAuthorizationCase,
  issuer: string,
  authorization = false,
): Promise<void> {
  if (authorization && isRedirect(response.status)) {
    const callback = new URL(response.headers.get("location") ?? "");
    // Redirects must target the registered URI, never a rejected requested URI.
    const registered = fixture.registration.metadata.redirect_uris as string[];
    if (!registered?.includes(fixture.authorization.redirectUri)) throw new Error("Rejected redirect URI must not receive a callback");
    const errors = callback.searchParams.getAll("error");
    if (errors.length !== 1 || !errors[0] || callback.searchParams.has("code")) throw new Error("Invalid OAuth error callback");
    if (errors[0] === "invalid_client") throw new Error("Invalid-client authorization failures must not redirect");
    callback.searchParams.delete("error");
    callback.searchParams.delete("error_description");
    callback.searchParams.delete("error_uri");
    callback.searchParams.set("code", "error-envelope-validation");
    validatedRedirectCode(
      new Response(null, { status: response.status, headers: { location: callback.toString() } }),
      fixture,
      issuer,
    );
  } else {
    const body = await response.clone().json().catch(() => undefined);
    // An unrecognized/incompatible client must not receive a redirect. Other
    // authorization errors for the registered callback must use that callback.
    if (authorization && body?.error !== "invalid_client" && (fixture.registration.metadata.redirect_uris as string[])?.includes(fixture.authorization.redirectUri)) {
      throw new Error("Registered authorization requests require an OAuth error callback");
    }
    if (response.status !== 400 && !(!authorization && response.status === 401 && body?.error === "invalid_client")) throw new Error("OAuth error response has invalid HTTP status");
    if (response.headers.has("location") || !isJsonResponse(response) ||
        !body || typeof body.error !== "string" || !body.error) {
      throw new Error("OAuth error response must be a JSON error envelope");
    }
  }
}

function validatedRedirectCode(
  response: Response,
  fixture: McpFnHostedAuthorizationCase,
  issuer: string,
): string {
  const location = response.headers.get("location");
  if (!location) throw new Error("Authorization callback is missing");
  const callback = new URL(location);
  const expected = new URL(fixture.authorization.redirectUri);
  const codes = callback.searchParams.getAll("code");
  const states = callback.searchParams.getAll("state");
  if (codes.length !== 1 || !codes[0] || states.length !== 1 || states[0] !== fixture.authorization.state) {
    throw new Error("Authorization callback code or state is invalid");
  }
  const issuers = callback.searchParams.getAll("iss");
  if (issuers.length > 1 || (issuers.length === 1 && issuers[0] !== issuer)) {
    throw new Error("Authorization callback issuer is invalid");
  }
  if (callback.protocol !== expected.protocol || callback.host !== expected.host ||
      callback.username !== expected.username || callback.password !== expected.password ||
      callback.pathname !== expected.pathname || callback.hash !== expected.hash ||
      [...new Set(expected.searchParams.keys())].some((key) =>
        JSON.stringify(callback.searchParams.getAll(key)) !== JSON.stringify(expected.searchParams.getAll(key)))) {
    throw new Error("Authorization callback destination is invalid");
  }
  return codes[0];
}

async function validatedTokenSet(response: Response): Promise<{ refresh_token?: unknown }> {
  if (response.status !== 200) throw new Error("Successful token responses must use HTTP 200");
  if (!isJsonResponse(response)) throw new Error("Token response must use a JSON media type");
  const value = await response.clone().json() as Record<string, unknown> | null;
  if (!value || typeof value.access_token !== "string" || !/^[A-Za-z0-9._~+/-]+=*$/.test(value.access_token) ||
      typeof value.token_type !== "string" || value.token_type.toLowerCase() !== "bearer") {
    throw new Error("Token response requires an access token and Bearer token type");
  }
  return value;
}

function isRedirect(status: number): boolean {
  return [301, 302, 303, 307, 308].includes(status);
}

function ensureTrailingSlash(value: string): URL {
  const url = new URL(value);
  if (!url.pathname.endsWith("/")) url.pathname += "/";
  return url;
}
