      const finishRedaction = beginTargetCredentialRedaction(target);
      try {
        try {
          await inspector.connect();
          const serialized = `${JSON.stringify(redactTargetCredentials(target, await inspector.snapshot(), { preserveKeys: true }), null, 2)}\n`;
          if (options.output) {
