    expect(await runCli(args, { stderr: () => {} })).toBe(2);
  } finally {
    state.failure = undefined;
    if (previous === undefined) delete process.env.MCPFN_CLEANUP_TEST_KEY;
    else process.env.MCPFN_CLEANUP_TEST_KEY = previous;
  }
});


