  const previous = process.env.MCPFN_CLEANUP_TEST_KEY;
  process.env.MCPFN_CLEANUP_TEST_KEY = "secret";
  let attempts = 0;
  const report = {
    formatVersion: 1 as const,
    kind: "mcpfn.official-conformance-report" as const,
    suiteVersion: "0.1.16",
    ok: false,
    exitCode: 1,
    stdout: "redacted output",
