    try { event = structuredClone(event); bytes = encodedBytes(event); }
    catch { this.droppedEvents += 1; return; }
    if (bytes > this.maxTimelineBytes) {
      event = {
        formatVersion: 1,
        source,
        kind,
        at,
        event: { truncated: true },
      };
